#pragma once
void testGlslPreprocessor(){
    using namespace bridge;using namespace bridge::shaderloader;
    const auto fails=[](auto fn){try{fn();}catch(const std::exception&){return true;}return false;};
    const auto compact=[](std::string text){text.erase(std::remove_if(text.begin(),text.end(),[](char c){return c==' '||c=='\t'||c=='\r'||c=='\n';}),text.end());return text;};
    const auto prepare=[](std::string body,const std::vector<PropertyMacro>& context=std::vector<PropertyMacro>{}){const auto files=PackSources::create({{"root.fsh","#version 330 core\n"+body}});return preparePackShader(*files,"root.fsh",context).glsl;};
    const auto write=[](const char* name,const std::string& text){std::ofstream output(std::string("outputs/native-renderer-verification/")+name,std::ios::binary);requireCPU(bool(output),"Cannot write GLSL preprocessing fixture.");output.write(text.data(),static_cast<std::streamsize>(text.size()));requireCPU(bool(output),"Truncated GLSL preprocessing fixture.");};
    std::ifstream input("outputs/native-renderer-verification/pack-source-fixture.bin",std::ios::binary);requireCPU(bool(input),"Missing GLSL snapshot fixture.");const std::vector<uint8_t> snapshot(std::istreambuf_iterator<char>(input),{});const auto files=PackSources::decode(snapshot);
    const std::vector<PropertyMacro> context={{"PACK_COLOR_OVERRIDE",std::nullopt},{"PACK_TEST_LEVEL","2"}};
    const auto vertex=preparePackShader(*files,"gbuffers_terrain.vsh",context),fragment=preparePackShader(*files,"gbuffers_terrain.fsh",context);
    const auto code=compact(fragment.glsl.text);requireCPU(code.find("returnvec4(0.2,0.4,0.8,1.0);")!=std::string::npos&&code.find("#define")==std::string::npos&&code.find("PACK_COLOR")==std::string::npos,"ZIP/include/GLSL conditions and function macros did not prepare expected source.");
    requireCPU(fragment.glsl.sourcePaths==fragment.expanded.sourcePaths&&fragment.glsl.version==330&&fragment.glsl.profile=="core"&&context[0].value==std::nullopt&&context[1].value=="2","GLSL preparation mutated provenance/context or version profile.");
    write("pack-glsl-positive.vert",vertex.glsl.text);write("pack-glsl-positive.frag",fragment.glsl.text);
    const auto computeFiles=PackSources::create({{"compute.csh","#version 450 core\n#define SIZE(x) (1 << (x))\n#define GROUP SIZE(2)\n#if GROUP == 4 && __VERSION__ >= 450\nlayout(local_size_x=GROUP) in;\n#else\n#error wrong group\n#endif\nvoid main(){}\n"}});
    const auto compute=preparePackShader(*computeFiles,"compute.csh",{});write("pack-glsl-compute.comp",compute.glsl.text);
    const auto badFiles=PackSources::create({{"negative.fsh","#version 330 core\n#include \"/macro/bad.glsl\"\nout vec4 color;\nvoid main(){color=badFunction();}\n"},{"macro/bad.glsl","#define BAD(x) vec4(x)\nvec4 badFunction(){return BAD(missingAfterMacro);}\n"}});
    const auto negative=preparePackShader(*badFiles,"negative.fsh",{});requireCPU(negative.glsl.sourcePaths[1]=="macro/bad.glsl","GLSL negative source-map mismatch.");write("pack-glsl-negative.frag",negative.glsl.text);
    const auto nested=compact(prepare("#define F(x) ((x)+1)\n#define ALIAS F\nconst int n=ALIAS(F(1));\n").text);requireCPU(nested.find("constintn=((((1)+1))+1);")!=std::string::npos,"Function alias rescan, argument prescan or nested function macro expansion failed.");
    const auto rescanned=compact(prepare("#define A 4\n#define ID(x) x\n#define EMPTY()\nint value=ID(A)+A;\nvoid main(){EMPTY()}\n").text);requireCPU(rescanned.find("intvalue=4+4;")!=std::string::npos&&rescanned.find("EMPTY")==std::string::npos,"Independent object macros, parameter rescan or empty function macro changed.");
    requireCPU(prepare("#define A 1 || 0\n#if A && 0\nfloat selected=1.0;\n#else\n#error implicit parentheses\n#endif").text.find("selected")!=std::string::npos,"GLSL object replacement inserted implicit parentheses.");
    requireCPU(compact(prepare("#define ADD(a,b) \\\n ((a)+(b))\nconst int line=__LINE__;\nconst int value=ADD(2,3);\n").text).find("constintline=4;")!=std::string::npos,"Spliced macro lines lost physical source line restoration.");
    const auto locationFiles=PackSources::create({{"root.vsh","#version 330 core\n#include \"lib/loc.glsl\"\nconst int parent=__LINE__;\n"},{"lib/loc.glsl","const int file=__FILE__;\nconst int line=__LINE__;\n"}});
    const auto locations=compact(preparePackShader(*locationFiles,"root.vsh",{}).glsl.text);requireCPU(locations.find("constintfile=1;")!=std::string::npos&&locations.find("constintline=2;")!=std::string::npos&&locations.find("constintparent=3;")!=std::string::npos,"Built-in GLSL locations were invented or lost include source IDs.");
    const auto es=PackSources::create({{"es.fsh","#version 300 es\n#ifdef GL_ES\nconst int v=__VERSION__;\n#else\n#error not ES\n#endif"}});requireCPU(compact(preparePackShader(*es,"es.fsh",{}).glsl.text).find("constintv=300;")!=std::string::npos,"GLSL ES facts did not come from the declared source version.");
    requireCPU(prepare("#ifdef GL_ES\n#error desktop source was labelled ES\n#endif\n").version==330,"Desktop GLSL source acquired GL_ES.");
    const auto ext=prepare("#extension all : warn\n#pragma optimize(on)\n#if 0\n#extension FAKE : require\n#error inactive\n#endif\n",{});
    requireCPU(ext.extensions.size()==1&&ext.extensions[0].name=="all","Inactive extensions or literal pragma processing changed.");
    const auto tokens=prepare("#define NAME changed\n// NAME and Grüß are a comment\nfloat NAME=1.0e-3; /* NAME */\n");requireCPU(compact(tokens.text).find("floatchanged=1.0e-3;")!=std::string::npos,"PP-number or comment tokenization changed GLSL meaning.");
    std::string oracle="#version 330 core\n";const std::vector<std::pair<std::string,bool>> expressions={{"1+2*3==7",true},{"(1+2)*3==9",true},{"16/4%3==1",true},{"(1<<4)==16",true},{"(16>>2)==4",true},{"(6&3)==2",true},{"(4|1)==5",true},{"(6^3)==5",true},{"~0 == -1",true},{"1<2 && 3>=3",true},{"1==2 || 4!=3",true},{"0?0:1",true},{"1?1:0",true},{"1?0:1",false},{"0 || 0 && 1",false},{"010==8 && 0x10==16",true},{"-9/2 == -4",true},{"-9%2 == -1",true}};
    size_t index=0;for(const auto& [expression,expected]:expressions){const auto body="#if "+expression+"\nconst int selected=1;\n#else\nconst int selected=0;\n#endif\n";requireCPU(compact(prepare(body).text).find(expected?"selected=1;":"selected=0;")!=std::string::npos,"GLSL conditional precedence/arithmetic result changed.");if(expression.find('?')!=std::string::npos)continue;oracle+="#if "+expression+"\nconst int probe"+std::to_string(index)+"=1;\n#else\nconst int probe"+std::to_string(index)+"=0;\n#endif\n";++index;}
    oracle+="out vec4 color;\nvoid main(){color=vec4(1.0);}\n";const auto oracleFiles=PackSources::create({{"oracle.fsh",oracle}});write("pack-glsl-oracle.raw.frag",oracle);write("pack-glsl-oracle.native.frag",preparePackShader(*oracleFiles,"oracle.fsh",{}).glsl.text);
    auto installed=fragment.glsl;const auto before=installed.text;
    for(const auto bad:{"#if UNKNOWN\n#endif","#ifdef UNKNOWN\n#endif","#define A A\nfloat x=A;","#define A B\n#define B A\nfloat x=A;","#define F(x) F(x)\nfloat x=F(1);","#define F(x) x\nfloat a=F(1,2);","#define F(x) x\nfloat a=F(\n1);","#define F(x) x\nfloat a=F\n(1);","#define F(a,a) a","#define F(GL_FAKE) GL_FAKE","#define F(__LINE__) __LINE__","#if +1\n#endif","#define F(...) x","#define F(x) #x","#define F(x) x##x","#define D defined(X)\n#if D\n#endif","#if 1/0\n#endif","#if 0&&(1/0)\n#endif","#if 1||(1/0)\n#endif","#if 1?1:(1/0)\n#endif","#if 0?(1/0):1\n#endif","#if 9223372036854775807+1\n#endif","#if (-9223372036854775807-1)/-1\n#endif","#if 3037000500*3037000500\n#endif","#if 1<<64\n#endif","#if -1>>1\n#endif","#if 1u\n#endif","#if 1.0\n#endif","#if 0\n","#else","#if 1\n#else\n#elif 1\n#endif","#define __LINE__ 1","#undef GL_ES","#define GL_FAKE 1","#pragma once","#warning not supported","#error fail","#extension all : require","#extension GL_ARB_gpu_shader5 : require\n#ifdef GL_ARB_gpu_shader5\n#endif","#version 330 core","float x=IRIS_JCPP_GLSL_VERSION;"}){
        requireCPU(fails([&]{installed=prepare(bad);})&&installed.text==before,"Malformed/unknown/unsupported GLSL preprocessing installed partial output.");
    }
    requireCPU(fails([&]{prepare("",{{"A","1"},{"A",std::nullopt}});}),"Duplicate GLSL context was accepted.");requireCPU(fails([&]{prepare("",{{"__VERSION__","450"}});}),"Caller spoofed a source-declared GLSL version.");
    requireCPU(fails([&]{prepare("#if 0\n#include absent\n#endif");}),"GLSL conditions hid missing includes before include-graph acquisition.");
    ExpandedShader malformed;malformed.sourcePaths={"root.vsh"};malformed.text="#version 330 core\n#line 3 99\n";requireCPU(fails([&]{GlslPreprocessor::prepare(malformed,{});}),"Invalid generated source ID was accepted.");
    malformed.text="float x;\n";requireCPU(fails([&]{GlslPreprocessor::prepare(malformed,{});}),"GLSL version was fabricated for an unversioned root.");
    std::string deep;for(unsigned i=0;i<33;++i)deep+="#if 1\n";requireCPU(fails([&]{prepare(deep);}),"GLSL conditional depth limit failed.");
    std::vector<PropertyMacro> many;for(unsigned i=0;i<513;++i)many.push_back({"X"+std::to_string(i),"1"});requireCPU(fails([&]{prepare("",many);}),"GLSL macro count limit failed.");
    std::string chain;for(unsigned i=0;i<34;++i)chain+="#define X"+std::to_string(i)+" X"+std::to_string(i+1)+"\n";chain+="#define X34 1\nfloat x=X0;\n";requireCPU(fails([&]{prepare(chain);}),"GLSL macro depth limit failed.");
    const std::string huge(64*1024+1,'a');requireCPU(fails([&]{prepare(huge);}),"GLSL logical line limit failed.");
    std::string output="#define X "+std::string(32*1024,'a')+"\n";for(unsigned i=0;i<9;++i)output+="X ";requireCPU(fails([&]{prepare(output);}),"GLSL expanded character limit failed.");
}
